<template><el-dialog :model-value="modelValue" title="导出模型" width="620" @close="$emit('update:modelValue',false)"><div class="export-options"><button v-for="item in formats" :key="item.value" :class="{selected:format===item.value}" @click="format=item.value"><b>{{item.label}}</b><span>{{item.description}}</span></button><button disabled><b>Isaac USD</b><span>NOT_AVAILABLE_LOCAL</span></button></div><label>输出文件或目录<el-input v-model="output" placeholder="例如 G:\workspace\robot.urdf"/></label><el-alert title="导出写入用户选择的位置，不修改源模型" type="info" :closable="false"/><template #footer><el-button @click="$emit('update:modelValue',false)">关闭</el-button><el-button type="primary" :disabled="!output" @click="runExport">导出</el-button></template></el-dialog></template>
<script setup lang="ts">import {ref} from 'vue';import {ElMessage} from 'element-plus';import {exportModel,type ExportFormat} from '@/api/export';defineProps<{modelValue:boolean}>();const emit=defineEmits(['update:modelValue']);const output=ref('');const format=ref<ExportFormat>('urdf');const formats:Array<{value:ExportFormat;label:string;description:string}>=[{value:'urdf',label:'URDF',description:'标准机器人描述'},{value:'package',label:'Portable Package',description:'模型与资源目录'},{value:'mjcf',label:'MJCF',description:'MuJoCo XML'},{value:'morphology',label:'Morphology JSON',description:'形态结构数据'}];async function runExport(){try{const result=await exportModel(format.value,output.value);ElMessage.success(`已导出：${result.output}`);emit('update:modelValue',false)}catch(error){ElMessage.error(String(error))}}</script>
